import styled from 'styled-components';

/**
 * This file contains shared styled components for algorithm visualizations
 */

// Main container for all visualizations
export const VisualizationContainer = styled.div`
  display: flex;
  flex-direction: column;
  width: 100%;
  min-height: 350px;
`;

// Container for displaying arrays or strings
export const ElementsContainer = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 2rem;
  flex-wrap: wrap;
  position: relative;
`;

// Box for displaying individual elements
export const ElementBox = styled.div`
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid ${props => {
    if (props.isPrimary) return 'var(--primary)';
    if (props.isSuccess) return '#4caf50';
    if (props.isWarning) return '#ff9800';
    if (props.isError) return '#f44336';
    if (props.isInfo) return '#2196f3';
    return '#e0e0e0';
  }};
  background-color: ${props => {
    if (props.isPrimary) return 'rgba(98, 0, 238, 0.1)';
    if (props.isSuccess) return 'rgba(76, 175, 80, 0.1)';
    if (props.isWarning) return 'rgba(255, 152, 0, 0.1)';
    if (props.isError) return 'rgba(244, 67, 54, 0.1)';
    if (props.isInfo) return 'rgba(33, 150, 243, 0.1)';
    return 'white';
  }};
  margin: 0 5px 10px;
  border-radius: var(--border-radius);
  font-weight: ${props => props.isBold ? 'bold' : 'normal'};
  position: relative;
`;

// Label for index positions
export const IndexLabel = styled.div`
  position: absolute;
  top: -25px;
  font-size: 0.75rem;
  color: var(--text-secondary);
`;

// Box for displaying status messages
export const StatusMessage = styled.div`
  text-align: center;
  margin-top: 1rem;
  padding: 0.75rem;
  border-radius: var(--border-radius);
  background-color: ${props => {
    if (props.type === 'success') return '#e8f5e9';
    if (props.type === 'info') return '#e3f2fd';
    if (props.type === 'warning') return '#fff3e0';
    if (props.type === 'error') return '#ffebee';
    return 'white';
  }};
  color: ${props => {
    if (props.type === 'success') return '#2e7d32';
    if (props.type === 'info') return '#1565c0';
    if (props.type === 'warning') return '#e65100';
    if (props.type === 'error') return '#c62828';
    return 'var(--text-primary)';
  }};
`;

// Container for data structures like stacks, queues, etc.
export const DataStructureContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 2rem;
`;

// Title for a section in the visualization
export const SectionTitle = styled.div`
  margin-bottom: 0.5rem;
  font-weight: 500;
  color: var(--text-primary);
`;

// Container for displaying items in a data structure
export const DataStructureBox = styled.div`
  display: flex;
  flex-direction: ${props => props.direction || 'column'};
  gap: 5px;
  min-height: ${props => props.minHeight || '100px'};
  min-width: ${props => props.minWidth || '250px'};
  padding: 15px;
  border: 1px dashed #e0e0e0;
  border-radius: var(--border-radius);
  position: relative;
`;

// Container for displaying key-value pairs
export const KeyValueContainer = styled.div`
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 1.5rem;
`;

// Container for a key-value pair
export const KeyValuePair = styled.div`
  display: flex;
  align-items: center;
  border: 1px solid #e0e0e0;
  border-radius: var(--border-radius);
  overflow: hidden;
`;

// Key part of a key-value pair
export const KeyBox = styled.div`
  padding: 8px 12px;
  background-color: #f5f5f5;
  font-weight: 500;
  border-right: 1px solid #e0e0e0;
`;

// Value part of a key-value pair
export const ValueBox = styled.div`
  padding: 8px 12px;
  background-color: white;
`;

// Container for results or final output
export const ResultsContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 1.5rem;
`;

// Single result item
export const ResultItem = styled.div`
  margin-bottom: 0.5rem;
`; 