import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import ControlPanel from './ControlPanel';
import {
  VisualizationContainer,
  StatusMessage,
  ResultsContainer,
  ResultItem
} from './VisualizationStyles';

const LinkedListsContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
  margin-bottom: 2rem;
`;

const LinkedList = styled.div`
  display: flex;
  align-items: center;
  position: relative;
  margin-bottom: 1rem;
`;

const ListLabel = styled.div`
  position: absolute;
  left: -40px;
  font-weight: 500;
  color: var(--text-primary);
`;

const LinkedListNode = styled.div`
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid ${props => {
    if (props.isActive) return 'var(--primary)';
    if (props.isResult) return '#4caf50';
    if (props.isSelected) return '#ff9800';
    return '#e0e0e0';
  }};
  background-color: ${props => {
    if (props.isActive) return 'rgba(98, 0, 238, 0.1)';
    if (props.isResult) return 'rgba(76, 175, 80, 0.1)';
    if (props.isSelected) return 'rgba(255, 152, 0, 0.1)';
    return 'white';
  }};
  margin: 0 2px;
  border-radius: 50%;
  position: relative;
  font-weight: ${props => props.isActive || props.isResult || props.isSelected ? 'bold' : 'normal'};
`;

const Arrow = styled.div`
  width: 20px;
  height: 2px;
  background-color: #e0e0e0;
  position: relative;
  
  &::after {
    content: '';
    position: absolute;
    right: 0;
    top: -3px;
    width: 0;
    height: 0;
    border-top: 4px solid transparent;
    border-bottom: 4px solid transparent;
    border-left: 7px solid #e0e0e0;
  }
`;

const ComparisonBox = styled.div`
  display: flex;
  align-items: center;
  gap: 0.5rem;
  justify-content: center;
  margin: 1rem 0;
  padding: 0.75rem;
  border: 1px dashed #e0e0e0;
  border-radius: var(--border-radius);
`;

const ExampleSection = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1rem;
`;

const ExampleButton = styled.button`
  padding: 0.5rem 1rem;
  background: ${props => props.isSelected ? 'var(--primary)' : '#f5f5f5'};
  color: ${props => props.isSelected ? 'white' : 'var(--text-primary)'};
  border: 1px solid ${props => props.isSelected ? 'var(--primary)' : '#e0e0e0'};
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 0.9rem;
  
  &:hover {
    background: ${props => props.isSelected ? 'var(--primary-dark)' : '#e0e0e0'};
  }
`;

const InputContainer = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
`;

const InputField = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const InputLabel = styled.label`
  margin-bottom: 0.5rem;
  font-weight: 500;
`;

const Input = styled.input`
  padding: 0.5rem;
  border: 1px solid #e0e0e0;
  border-radius: var(--border-radius);
  width: 200px;
  text-align: center;
  font-family: monospace;
`;

const HelpText = styled.div`
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-top: 0.25rem;
  text-align: center;
`;

const DEFAULT_LIST1 = [1, 2, 4];
const DEFAULT_LIST2 = [1, 3, 4];
// Merged list should be [1, 1, 2, 3, 4, 4]

const EXAMPLES = [
  { label: "Example 1", list1: [1, 2, 4], list2: [1, 3, 4] },
  { label: "Example 2", list1: [1, 3, 5], list2: [2, 4, 6] },
  { label: "Example 3", list1: [], list2: [0] },
  { label: "Example 4", list1: [5], list2: [1, 2, 4] }
];

const MergeTwoSortedListsVisualization = () => {
  const [list1, setList1] = useState(DEFAULT_LIST1);
  const [list2, setList2] = useState(DEFAULT_LIST2);
  const [mergedList, setMergedList] = useState([]);
  const [currentStep, setCurrentStep] = useState(0);
  const [pointer1, setPointer1] = useState(0);
  const [pointer2, setPointer2] = useState(0);
  const [currentComparison, setCurrentComparison] = useState(null);
  const [selectedNode, setSelectedNode] = useState(null);
  const [message, setMessage] = useState({ text: 'Click "Start" to begin the visualization.', type: 'info' });
  const [isRunning, setIsRunning] = useState(false);
  const [speed, setSpeed] = useState(1000); // in milliseconds
  const [isComplete, setIsComplete] = useState(false);
  const [list1Input, setList1Input] = useState(DEFAULT_LIST1.join(','));
  const [list2Input, setList2Input] = useState(DEFAULT_LIST2.join(','));
  const [selectedExample, setSelectedExample] = useState(0);
  
  const reset = () => {
    setCurrentStep(0);
    setPointer1(0);
    setPointer2(0);
    setMergedList([]);
    setCurrentComparison(null);
    setSelectedNode(null);
    setMessage({ text: 'Click "Start" to begin the visualization.', type: 'info' });
    setIsRunning(false);
    setIsComplete(false);
  };
  
  const start = () => {
    reset();
    setIsRunning(true);
  };
  
  const nextStep = () => {
    if (!isComplete) {
      setCurrentStep(prev => prev + 1);
    } else {
      setIsRunning(false);
    }
  };
  
  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(prev => prev - 1);
    }
  };
  
  // Handle input changes
  const handleList1Change = (e) => {
    setList1Input(e.target.value);
    try {
      const newList = e.target.value.split(',').map(item => parseInt(item.trim())).filter(num => !isNaN(num));
      setList1(newList);
      setSelectedExample(-1); // Deselect any example
      reset();
    } catch (error) {
      console.error("Invalid input format for list 1");
    }
  };
  
  const handleList2Change = (e) => {
    setList2Input(e.target.value);
    try {
      const newList = e.target.value.split(',').map(item => parseInt(item.trim())).filter(num => !isNaN(num));
      setList2(newList);
      setSelectedExample(-1); // Deselect any example
      reset();
    } catch (error) {
      console.error("Invalid input format for list 2");
    }
  };
  
  const selectExample = (index) => {
    setSelectedExample(index);
    const example = EXAMPLES[index];
    setList1(example.list1);
    setList2(example.list2);
    setList1Input(example.list1.join(','));
    setList2Input(example.list2.join(','));
    reset();
  };
  
  useEffect(() => {
    if (!isRunning) return;
    
    // If we've reached the end of both lists, we're done
    if (pointer1 >= list1.length && pointer2 >= list2.length) {
      setMessage({ 
        text: 'Merge complete! Both lists have been fully processed.', 
        type: 'success' 
      });
      setIsRunning(false);
      setIsComplete(true);
      setCurrentComparison(null);
      return;
    }
    
    // If we've reached the end of list1, add the rest of list2
    if (pointer1 >= list1.length) {
      const value = list2[pointer2];
      setCurrentComparison({ list1: null, list2: value, selected: 'list2' });
      setSelectedNode({ list: 'list2', index: pointer2 });
      
      setMessage({ 
        text: `List1 is exhausted. Adding ${value} from list2.`, 
        type: 'info' 
      });
      
      const timer = setTimeout(() => {
        setMergedList(prev => [...prev, value]);
        setPointer2(pointer2 + 1);
        
        const nextTimer = setTimeout(() => {
          nextStep();
        }, speed / 2);
        
        return () => clearTimeout(nextTimer);
      }, speed);
      
      return () => clearTimeout(timer);
    }
    
    // If we've reached the end of list2, add the rest of list1
    if (pointer2 >= list2.length) {
      const value = list1[pointer1];
      setCurrentComparison({ list1: value, list2: null, selected: 'list1' });
      setSelectedNode({ list: 'list1', index: pointer1 });
      
      setMessage({ 
        text: `List2 is exhausted. Adding ${value} from list1.`, 
        type: 'info' 
      });
      
      const timer = setTimeout(() => {
        setMergedList(prev => [...prev, value]);
        setPointer1(pointer1 + 1);
        
        const nextTimer = setTimeout(() => {
          nextStep();
        }, speed / 2);
        
        return () => clearTimeout(nextTimer);
      }, speed);
      
      return () => clearTimeout(timer);
    }
    
    // Compare current values from both lists
    const value1 = list1[pointer1];
    const value2 = list2[pointer2];
    setCurrentComparison({ list1: value1, list2: value2, selected: value1 <= value2 ? 'list1' : 'list2' });
    
    // Select the smaller value
    if (value1 <= value2) {
      setSelectedNode({ list: 'list1', index: pointer1 });
      
      setMessage({ 
        text: `Comparing ${value1} and ${value2}. ${value1} is smaller or equal, adding from list1.`, 
        type: 'info' 
      });
      
      const timer = setTimeout(() => {
        setMergedList(prev => [...prev, value1]);
        setPointer1(pointer1 + 1);
        
        const nextTimer = setTimeout(() => {
          nextStep();
        }, speed / 2);
        
        return () => clearTimeout(nextTimer);
      }, speed);
      
      return () => clearTimeout(timer);
    } else {
      setSelectedNode({ list: 'list2', index: pointer2 });
      
      setMessage({ 
        text: `Comparing ${value1} and ${value2}. ${value2} is smaller, adding from list2.`, 
        type: 'info' 
      });
      
      const timer = setTimeout(() => {
        setMergedList(prev => [...prev, value2]);
        setPointer2(pointer2 + 1);
        
        const nextTimer = setTimeout(() => {
          nextStep();
        }, speed / 2);
        
        return () => clearTimeout(nextTimer);
      }, speed);
      
      return () => clearTimeout(timer);
    }
  }, [currentStep, isRunning, list1, list2, pointer1, pointer2, speed]);
  
  return (
    <VisualizationContainer>
      <ControlPanel
        onStart={start}
        onNext={nextStep}
        onPrev={prevStep}
        onReset={reset}
        isRunning={isRunning}
        canGoNext={!isComplete}
        canGoPrev={currentStep > 0}
        speed={speed}
        onSpeedChange={setSpeed}
        showPrev={true}
      />
      
      <ExampleSection>
        <div style={{ marginRight: '0.5rem' }}>Examples:</div>
        {EXAMPLES.map((example, index) => (
          <ExampleButton
            key={index}
            isSelected={selectedExample === index}
            onClick={() => selectExample(index)}
            disabled={isRunning}
          >
            {example.label}
          </ExampleButton>
        ))}
      </ExampleSection>
      
      <InputContainer>
        <InputField>
          <InputLabel>First List:</InputLabel>
          <Input 
            value={list1Input}
            onChange={handleList1Change}
            disabled={isRunning}
            placeholder="1,2,4"
          />
        </InputField>
        
        <InputField>
          <InputLabel>Second List:</InputLabel>
          <Input 
            value={list2Input}
            onChange={handleList2Change}
            disabled={isRunning}
            placeholder="1,3,4"
          />
        </InputField>
      </InputContainer>
      
      <LinkedListsContainer>
        <LinkedList>
          <ListLabel>list1:</ListLabel>
          {list1.length === 0 ? (
            <HelpText>Empty List</HelpText>
          ) : (
            list1.map((value, index) => (
              <React.Fragment key={index}>
                <LinkedListNode 
                  isActive={index === pointer1}
                  isSelected={selectedNode?.list === 'list1' && selectedNode?.index === index}
                >
                  {value}
                </LinkedListNode>
                {index < list1.length - 1 && <Arrow />}
              </React.Fragment>
            ))
          )}
        </LinkedList>
        
        <LinkedList>
          <ListLabel>list2:</ListLabel>
          {list2.length === 0 ? (
            <HelpText>Empty List</HelpText>
          ) : (
            list2.map((value, index) => (
              <React.Fragment key={index}>
                <LinkedListNode 
                  isActive={index === pointer2}
                  isSelected={selectedNode?.list === 'list2' && selectedNode?.index === index}
                >
                  {value}
                </LinkedListNode>
                {index < list2.length - 1 && <Arrow />}
              </React.Fragment>
            ))
          )}
        </LinkedList>
        
        {mergedList.length > 0 && (
          <LinkedList>
            <ListLabel>merged:</ListLabel>
            {mergedList.map((value, index) => (
              <React.Fragment key={index}>
                <LinkedListNode isResult>
                  {value}
                </LinkedListNode>
                {index < mergedList.length - 1 && <Arrow />}
              </React.Fragment>
            ))}
          </LinkedList>
        )}
      </LinkedListsContainer>
      
      {currentComparison && (
        <ComparisonBox>
          <div>Comparing:</div>
          <div style={{ 
            fontWeight: currentComparison.selected === 'list1' ? 'bold' : 'normal',
            color: currentComparison.selected === 'list1' ? 'var(--primary)' : 'inherit'
          }}>
            {currentComparison.list1 !== null ? currentComparison.list1 : "empty"}
          </div>
          <div>vs</div>
          <div style={{ 
            fontWeight: currentComparison.selected === 'list2' ? 'bold' : 'normal',
            color: currentComparison.selected === 'list2' ? 'var(--primary)' : 'inherit'
          }}>
            {currentComparison.list2 !== null ? currentComparison.list2 : "empty"}
          </div>
          {currentComparison.selected && <div>→ Selecting: {currentComparison.selected === 'list1' ? 'list1' : 'list2'}</div>}
        </ComparisonBox>
      )}
      
      <StatusMessage type={message.type}>
        {message.text}
      </StatusMessage>
      
      {isComplete && (
        <ResultsContainer>
          <ResultItem>
            <strong>Final Merged List:</strong> [{mergedList.join(', ')}]
          </ResultItem>
        </ResultsContainer>
      )}
    </VisualizationContainer>
  );
};

export default MergeTwoSortedListsVisualization; 